INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('6dc14f5a-3ada-4a3a-9e74-b61dd08fbe51', NULL, NULL, NULL, '{"summary": "Clínica integrativa validada e sem dívidas, mas frágil em digital e marca; precisa escalar além da fundadora.", "threats": [{"source": "análise de mercado", "content": "Rivalidade alta com clínicas premium, franquias e spas urbanos em SP", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Regulação ANVISA e fiscalização de publicidade elevam risco jurídico", "confidence": "Média"}, {"source": "análise de mercado", "content": "Insumos atrelados ao dólar (USD/BRL 5.3723) comprimem margem", "confidence": "Alta"}, {"source": "análise de mercado", "content": "CAC digital em alta e cliente endividado reduzem conversão", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Missão e visão claras de bem-estar integral e humanizado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Modelo bootstrapped reduz risco financeiro com SELIC a 14,90%", "confidence": "Média"}, {"source": "fato", "content": "Receita anual entre R$1,2M e R$1,5M comprova tração", "confidence": "Alta"}, {"source": "fato", "content": "Experiência leve, com bom humor e conexão com a natureza", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Alta dependência da fundadora Thalita na agenda e decisão", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Baixa presença digital: site e funil online pouco estruturados", "confidence": "Média"}, {"source": "estimativa", "content": "Oferta ainda não reflete plenamente o conceito de bem-estar integral", "confidence": "Média"}, {"source": "análise de mercado", "content": "Possível confusão com outras marcas \"Vallen\" na saúde em SP", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Demanda crescente por saúde integrativa corpo-mente e autocuidado", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Clientes seletivos buscam experiências premium com alto valor percebido", "confidence": "Média"}, {"source": "análise de mercado", "content": "SELIC a 14,90% favorece clínicas sem dívidas com caixa para investir", "confidence": "Média"}, {"source": "estimativa", "content": "Ecossistema digital e parcerias ampliam oferta de bem-estar integral", "confidence": "Média"}]}'::jsonb, '{"legal": ["Licença Sanitária, CNES e RT criam 3 pontos de falha regulatória que podem paralisar operação.", "LGPD na saúde exige gestão de dados sensíveis; erro em prontuário digital gera risco jurídico alto.", "Regras de consentimento informado e biossegurança ampliam responsabilidade civil em cada procedimento."], "social": ["Público B2C A/B mais seletivo prioriza experiências de alto valor percebido em saúde e beleza.", "Busca pós-pandemia por autocuidado e bem-estar integral corpo+mente fortalece proposta da clínica.", "Medo da banalização estética aumenta peso de confiança, empatia e bom humor na escolha da clínica."], "summary": "SELIC alta, câmbio caro e consumidor seletivo favorecem clínicas sem dívidas, mas expõem riscos regulatórios, digitais e ambientais. Profissionalizar gestão, compliance e presença online é chave para sustentar o posicionamento em bem-estar integral.", "economic": ["SELIC 14.90% a.a. encarece crédito ao consumidor, mas favorece clínica bootstrapped sem dívidas.", "IPCA 0.09% (12 meses) dá preços estáveis, porém dólar R$ 5.36/USD aumenta custo de insumos.", "PIB 12m 3.20 % e serviços +0.60 % sugerem demanda estável, porém mais seletiva e exigente."], "political": ["Reformas sanitárias em debate (dados até 01/12/2025) podem apertar regras para clínicas de estética.", "Novas normas ANVISA p/ procedimentos estéticos invasivos exigem mais treinamento e protocolos.", "Fiscalização de publicidade médica/estética em alta pode limitar marketing leve e bem-humorado."], "environmental": ["Tendência de sustentabilidade em cosméticos exige fornecedores verdes, mesmo com dólar R$ 5.36/USD.", "Proposta de conexão com a natureza demanda práticas eco reais em clínica, não só discurso de marca.", "Consumidor seletivo pode punir greenwashing; transparência ambiental vira diferencial competitivo."], "technological": ["Adoção média de tecnologia torna telemedicina e agendamento online mínimos esperados em 2025.", "Maturidade digital 2 e quase nenhum site/redes visíveis elevam risco de invisibilidade no B2C A/B.", "CAC digital em alta pressiona margem; ecossistema próprio de conteúdo pode reduzir dependência paga."]}'::jsonb, '{"summary": "Nicho de saúde e estética integrativa cresce com PIB 3.20% e serviços em alta, mas há forte rivalidade, poder do comprador e muitos substitutos. A atratividade depende de consolidar marca integrativa, ecossistema de parcerias e uso intensivo de dados e IA.", "buyer_power": "Consumidor endividado e seletivo (SELIC 14.90% a.a., desemprego 5.6%) eleva poder de barganha; Vallen deve ampliar valor percebido e recorrência via programas de bem-estar integral e experiência premium.", "supplier_power": "Insumos em dólar (USD/BRL 5.3723) e equipamentos caros pressionam margem, apesar da cadeia estável; Vallen deve negociar volume, prazos e mix sustentável para proteger lucro em cenário de SELIC 14.90% a.a.", "disruption_ai_data": "Adoção digital média e CAC online em alta tornam IA crítica; grandes redes já usam dados para personalizar ofertas. Vallen deve estruturar CRM, jornada RACE e automações éticas para competir por atenção e recorrência.", "threat_substitutes": "Procedimentos baratos por não-especialistas, clínicas populares e apps de autocuidado ampliam substitutos; Vallen deve educar sobre segurança, resultados e proposta integrativa corpo-mente para evitar fuga por preço.", "competitive_rivalry": "Alta rivalidade em SP: mercado fragmentado, franquias de estética e boutiques premium disputam público A/B; Vallen precisa diferenciação forte em bem-estar integral e experiência leve alinhada à missão.", "threat_new_entrants": "Barreiras médias (ANVISA, RT, custo de tecnologia) não impedem avanço de franquias de estética; Vallen precisa fortalecer marca, protocolos exclusivos e comunidade para desmotivar novos entrantes locais.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Construir posicionamento robusto em bem-estar integral, com protocolos proprietários e linguagem própria, reduzindo dependência da fundadora e blindando contra rivalidade e substitutos.", "Negociar insumos dolarizados (USD/BRL 5.3723) e revisar portfólio para proteger margem, priorizando fornecedores sustentáveis e contratos que atenuem impacto cambial e de SELIC 14.90% a.a.", "Estruturar ecossistema de parcerias (psicologia, nutrição, fitness, marcas verdes) para aumentar REACH/ENGAGE com indicações qualificadas e experiências combinadas de alto valor percebido.", "Elevar maturidade digital e de dados (CRM, automação, uso de IA em marketing) para reduzir CAC, personalizar ofertas ao longo da jornada RACE e criar recorrência alinhada à missão da Vallen Clinic."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Tendências de saúde integrativa e sustentabilidade favorecem alianças com psicólogos, nutricionistas, academias e marcas verdes; ecossistema robusto amplia alcance, indicações qualificadas e fidelização B2C.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "Em 90 dias, Vallen estrutura gestão básica, ativa presença digital e lança 2 programas integrais, reduzindo dependência da fundadora e preparando validação e escala.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Implantar base mínima de gestão e governança clínica reduzindo a dependência da fundadora", "investment": "R$ 10-20 mil", "key_results": ["Mapear 4 processos críticos com fluxos aprovados (Resp.: Coord. Adm.)", "Definir organograma com 3 funções-chave formalizadas (Resp.: Thalita)", "Criar 6 indicadores básicos definidos e registrados (Resp.: Coord. Adm.)"], "aligned_recommendation": "Implantar gestão profissional, governança clínica e sucessão para reduzir dependência da fundadora"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Estruturar presença digital básica e jornada de agendamento alinhadas ao bem-estar integral", "investment": "R$ 20-40 mil", "key_results": ["Publicar 1 site institucional no ar com captação ativa (Resp.: Mkt)", "Implantar 1 funil digital com agendamento online testado (Resp.: Recepção)", "Configurar 3 fluxos de CRM básicos ativos (Resp.: Mkt)"], "aligned_recommendation": "Construir ecossistema digital de captação e fidelização alinhado ao bem-estar integral"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Lançar programas de bem-estar integral recorrentes e integrar gestão de desempenho", "investment": "R$ 30-50 mil", "key_results": ["Lançar 2 programas de bem-estar integral com protocolos definidos (Resp.: RT)", "Treinar 4 profissionais nos novos programas e experiência Vallen (Resp.: RH)", "Formalizar 1 painel mensal com 5 indicadores-chave (Resp.: Coord. Adm.)"], "aligned_recommendation": "Estruturar portfólio de bem-estar integral e programas recorrentes de alta experiência"}], "success_metrics": ["Organograma mínimo implantado e 70% dos processos críticos documentados até o mês 3", "Site e funil digital ativos gerando ao menos 30 leads qualificados/mês ao final de 90 dias", "2 programas de bem-estar integral lançados com mínimo de 10 clientes pilotos em 90 dias"], "execution_phases": {"scale": {"focus": "Expansão controlada", "duration": "Meses 7-12", "objectives": ["Expandir programas validados para maior base de clientes com foco em recorrência", "Elevar maturidade digital e de governança garantindo experiência consistente"], "key_results": ["Alcançar 30% da receita em programas recorrentes até o mês 12", "Manter NPS ≥ 85 com ocupação média de 80% das agendas até o mês 12"], "prerequisites": ["Validação bem-sucedida dos programas e jornada digital na Fase 2", "Métricas de satisfação e adesão dentro das metas definidas"], "investment_range": "R$ 100-150 mil"}, "foundation": {"focus": "Estruturação", "duration": "Meses 1-3", "objectives": ["Profissionalizar gestão e governança clínica mínima da Vallen Clinic", "Construir presença digital essencial alinhada à missão de bem-estar integral"], "key_results": ["Ter 1 organograma e 10 processos críticos formalizados até o mês 3", "Operar 1 site e 1 funil digital com registro mensal de leads até o mês 3"], "investment_range": "R$ 90-140 mil", "capacity_requirements": {"team": "6-8 pessoas núcleo (fundadora, RT, coord. administrativa, recepção, marketing, financeiro)", "dependencies": ["Parecer jurídico para contratos, LGPD e termos de consentimento", "Contratação/configuração de ferramentas de agenda online e CRM"], "skills_needed": ["Gestão clínica e de processos", "Marketing digital e CRM", "Atendimento humanizado", "Gestão financeira básica", "LGPD e compliance em saúde"]}}, "validation": {"focus": "Pilotos", "duration": "Meses 4-6", "objectives": ["Validar programas de bem-estar integral em pilotos controlados", "Testar jornada digital integrada à experiência presencial e remota"], "key_results": ["Concluir 3 pilotos de programas com NPS ≥ 80 até o mês 6", "Gerar 50 agendamentos online em 3 meses com taxa de comparecimento ≥ 70%"], "prerequisites": ["Fase 1 concluída com processos e indicadores mínimos operando", "Aprovações jurídicas e sanitárias obtidas para novos programas"], "investment_range": "R$ 80-140 mil"}}, "total_investment": "R$ 60-110 mil", "capacity_assessment": {"blockers": ["Alta dependência operacional e comercial da fundadora", "Baixa estruturação digital e de processos internos", "Custo de mídia digital elevado em cenário de SELIC 14,90% a.a."], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Parcial"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Implementar gestão básica, criar site institucional, ativar Google Meu Negócio e lançar 1º programa integral piloto", "Médio Prazo (6-12 meses): Escalar presença digital com funil de captação, padronizar jornadas de atendimento e lançar plano de assinatura recorrente", "Longo Prazo (12+ meses): Consolidar ecossistema integrativo com parcerias estratégicas, avaliar expansão física ou franquia e posicionar Thalita como embaixadora da marca"], "key_findings": ["Modelo bootstrapped é vantagem competitiva em cenário de juros altos, permitindo investir em digital sem pressão de dívida", "Transição de clínica para ecossistema integrativo recorrente pode elevar LTV em 40-60% com programas de assinatura", "Profissionalização da gestão é pré-requisito para qualquer escala - fundadora deve migrar para papel estratégico"], "main_findings": ["Força: Faturamento validado sem dívidas e posicionamento humanizado único em estética integrativa", "Fraqueza: Alta dependência da fundadora e presença digital praticamente inexistente", "Oportunidade: Mercado de bem-estar integral em expansão pós-pandemia com consumidor buscando experiências premium", "Ameaça: Rivalidade intensa, CAC digital em alta e risco regulatório crescente em publicidade estética"], "important_notes": ["Ausência de site/redes verificáveis é risco crítico de aquisição de clientes", "SELIC a 14.90% favorece bootstrapped, mas limita parcelamento do consumidor", "Homônimos ''Vallen'' em SP podem gerar confusão de marca - avaliar proteção"], "central_challenge": "Transformar a Vallen Clinic de uma operação centrada na fundadora em um ecossistema integrativo escalável, com presença digital robusta e modelo de receita recorrente.", "executive_summary": "A Vallen Clinic possui faturamento validado (R$1.2-1.5M) e posicionamento diferenciado em bem-estar integrativo, mas enfrenta fragilidade crítica: dependência da fundadora e ausência digital. O caminho estratégico exige profissionalizar gestão, construir presença online e criar programas recorrentes que escalem além de Thalita Mendes, capturando o crescimento do setor de saúde integrativa.", "strategic_priorities": ["Estruturar governança e processos que operem independente da fundadora", "Construir presença digital mínima viável (site + funil de captação)", "Lançar 2 programas integrais recorrentes para validar modelo escalável"], "consistency_validation": {"flags": ["Capacidade: Equipe atual (estimada 5-20) pode não suportar simultaneamente operação + transformação digital - considerar contratação pontual ou consultoria", "Marca: Risco de colisão com homônimos ''Vallen'' em SP não está mitigado - recomenda-se consulta jurídica de PI"], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Priorizar profissionalização da gestão e construção digital nos próximos 90 dias. Sem isso, qualquer estratégia de crescimento será limitada pela capacidade individual da fundadora."}'::jsonb, '{"sam": "R$ 30M - 80M", "som": "R$ 2,5M - 6M", "tam": "R$ 60B - 90B", "cagr": "+17% a.a. (baseado em: benchmark Saúde/HealthTech Brasil + tendências pós-pandemia)", "summary": "Mercado de estética/bem-estar em SP é amplo; Vallen pode evoluir de ~R$1,5M para R$2,5-6M/ano com boa execução.", "assumptions": ["TAM estética≈20% do mercado Saúde R$300-500B/ano Brasil (benchmark setorial).", "SAM SP classe A/B≈0,05-0,1% do TAM, foco zona oeste/sul (restrição geográfica).", "SOM PME estabelecida projeta 3-20% do SAM (faixas conservadora a otimista)."], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 2,5M - 6M", "market_share": "8-12% do SAM"}, "optimistic": {"probability": 20, "value_range": "R$ 4M - 10M", "market_share": "12-20% do SAM"}, "conservative": {"probability": 30, "value_range": "R$ 1M - 2,5M", "market_share": "3-5% do SAM"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 60B - 90B"}, "optimistic": {"probability": 20, "value_range": "R$ 80B - 120B"}, "conservative": {"probability": 30, "value_range": "R$ 50B - 70B"}}, "confidence_level": 60, "calculation_notes": "Partimos de Saúde Brasil R$300-500B, estimamos estética≈20%, depois frações para SP classe A/B e share da Vallen.", "data_sources_used": {"direct_data": ["Receita anual Vallen informada R$1,2-1,5M (company_data/submitted_data)."], "proxy_calculations": ["SAM≈0,05-0,1% do TAM para área de influência em SP classe A/B.", "SOM estimado como 3-20% do SAM, alinhado à receita atual e teto R$2-10M/ano."], "benchmark_extrapolations": ["TAM Saúde/HealthTech Brasil R$300-500B, crescimento 15-20% a.a. (benchmark fornecido).", "Ajuste para estética/bem-estar B2C Brasil≈20% do mercado Saúde total."]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "realistic"}'::jsonb, '{"summary": "Vallen já compete bem em experiência e propósito, mas perde para clínicas premium em digital, escala e branding. Profissionalizar gestão e marketing pode liberar crescimento relevante no nicho A/B em SP.", "best_practices": ["Propósito claro de bem-estar integral, leveza e sustentabilidade, alinhado às tendências de consumo.", "Modelo bootstrapped, sem dívidas relevantes, resiliente ao cenário de juros SELIC a 14,90% a.a.", "Experiência acolhedora e humanizada como eixo central, alinhada ao movimento de clínicas boutique."], "performance_gaps": ["Baixa presença digital estruturada (site, SEO e funil de leads), limitando alcance além do bairro.", "Dependência operacional e comercial da fundadora, sem processos replicáveis e playbooks claros.", "Posicionamento de bem-estar integral pouco traduzido em ofertas, jornadas e comunicação prática."], "competitors_analyzed": ["Clínicas de Dermatologia e Estética Premium em SP", "Spas Urbanos de Luxo", "Franquias de estética popular"]}'::jsonb, '{"raise": ["Protocolos integrativos corpo-mente personalizados com metas mensuráveis", "Experiência sensorial biofílica que conecta clínica à natureza urbana", "Transparência em resultados com dashboards de bem-estar para clientes"], "create": ["Clube Vallen de bem-estar integral com planos recorrentes e curadoria 360º", "Plataforma digital de autocuidado guiado com IA e suporte humano híbrido", "Formação Vallen de cuidadores e parceiros para escalar o método além da fundadora"], "reduce": ["Dependência de equipamentos caros como principal argumento de qualidade", "Campanhas promocionais de preço e descontos sazonais agressivos", "Complexidade de cardápio com dezenas de procedimentos pouco integrados"], "summary": "Vallen Clinic migra de clínica de estética para ecossistema integrativo, recorrente, digital e escalável além da fundadora.", "eliminate": ["Atendimentos centrados na fundadora como único diferencial de valor", "Pacotes de procedimentos avulsos sem vínculo com jornada de bem-estar", "Ambiente clínico padrão, neutro e impessoal típico de estética premium"], "new_value_curve": "Da estética de procedimento para ecossistema de bem-estar integral recorrente e leve."}'::jsonb, '{"summary": "Potencializar aquisição digital e parcerias, padronizar jornadas integrativas e criar planos recorrentes, elevando LTV sem depender da fundadora.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Atrair via Instagram, Google Perfil da Empresa e parcerias com spas/yoga focando saúde integrativa", "Engage: Nutrir leads com conteúdos leves de bem-estar e atendimento rápido via WhatsApp/DM humanizado", "Activate: Oferecer consulta integrativa de boas-vindas com preço ancorado e agenda desatrelada da fundadora", "Propagate: Criar programa de indicações com bônus em serviços relaxantes e compartilháveis nas redes"], "metrics": ["CAC por canal (Instagram, Google, parcerias)", "Taxa de conversão lead → primeira consulta", "Coeficiente viral (novos clientes por indicação)"], "bottleneck": "Baixa presença digital estruturada e funil online frágil, ainda muito dependente da imagem da fundadora"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Padronizar jornadas integrativas corpo-mente com protocolos replicáveis pela equipe, além da fundadora", "Convert: Empacotar planos mensais/trimestrais de cuidado contínuo com upgrades opcionais por sessão", "Loop Back: Automatizar follow-ups via WhatsApp/CRM com check-ins de bem-estar e ofertas personalizadas", "Expand: Criar produtos e combos de experiências integrativas para elevar ticket médio e LTV"], "metrics": ["LTV por persona e por plano integrativo", "Taxa de recompra e adesão a planos recorrentes", "Receita de expansão por upsell/cross-sell de serviços e produtos"], "bottleneck": "Protocolos e oferta pouco padronizados e centralizados na fundadora, limitando escala, recorrência e monetização"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece em 14.90% a.a., inflação em 0.09% (12 meses) e PIB em 2.20% indicam crescimento moderado. Câmbio em R$ 5.36/USD pressiona insumos importados, enquanto serviços (+0.60%) seguem firmes. Cliente segue seletivo; Vallen cresce pouco acima do mercado, exigindo gestão enxuta, digitalização e fortalecimento da marca além da fundadora.", "probability": 60, "required_actions": ["Mapear todas as dependências da Thalita Mendes e criar coordenação clínica e de experiência com metas claras", "Implementar gestão financeira mensal com DRE simples, metas de margem por serviço e política de reajuste anual", "Lançar base digital mínima: site institucional, agendamento online e funil de conteúdo em bem-estar integral", "Estruturar programa de compliance (ANVISA, CNES, LGPD) com checklists, treinamentos e revisão de contratos"]}, "summary": "O principal risco para a Vallen Clinic é a combinação de juros altos, câmbio pressionado e maior rigor regulatório, em um mercado digitalmente competitivo. Profissionalizar gestão, reduzir dependência da fundadora, fortalecer presença online e estruturar compliance são chaves para capturar o cenário otimista e resistir ao pessimista.", "optimistic": {"name": "Cenário Otimista", "description": "Com SELIC em 14.90% a.a. caindo gradualmente e PIB em 2.20% ao ano, serviços (+0.60%) e busca por bem-estar crescem. Câmbio estabiliza perto de R$ 5.36/USD, mantendo custos sob controle. Consumidor seletivo privilegia clínicas sem dívidas; Vallen consolida posição premium integral e reduz dependência da fundadora.", "probability": 20, "required_actions": ["Escalar o conceito de bem-estar integral com novos protocolos e linhas de serviço alinhados à missão", "Documentar e padronizar atendimentos da fundadora, criando trilhas de formação interna para replicar o padrão Vallen", "Investir forte em branding e presença digital sustentável, reforçando leveza, humor e conexão com a natureza"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Alta prolongada da SELIC acima de 14.90% a.a., PIB abaixo de 2.20% e desemprego acima de 5.60% reduzem demanda por estética premium. Câmbio supera R$ 5.36/USD, encarecendo insumos. Reguladores endurecem ANVISA e LGPD, elevando custos. Vallen sofre pressão de preço de franquias populares e risco de ociosidade em agenda e equipe.", "probability": 20, "required_actions": ["Proteger caixa: revisar custos fixos, alongar prazos com fornecedores e priorizar serviços de maior margem", "Renegociar contratos de insumos atrelados ao dólar e buscar alternativas nacionais sem comprometer qualidade", "Criar pacotes essenciais e planos de assinatura de bem-estar, mantendo experiência leve com ticket mais acessível"]}, "mitigation_tactics": ["Construir reserva de caixa equivalente a 6–9 meses de despesas fixas para suportar juros altos e oscilações de demanda", "Formalizar processos clínicos e de atendimento em manuais, treinando equipe para reduzir dependência da fundadora", "Implantar programa contínuo de compliance (ANVISA, CNES, LGPD), com auditorias internas e revisão de comunicação", "Diversificar aquisição de clientes com SEO local, parcerias e indicações, reduzindo dependência de mídia paga cara"], "early_warning_signals": ["Movimentos rápidos da SELIC em relação aos 14.90% a.a. e encarecimento do crédito ao consumidor parcelado", "Câmbio afastando-se de R$ 5.36/USD e reajustes frequentes de fornecedores de insumos e equipamentos importados", "Aumento de fiscalizações e novas normas em estética e publicidade, além de aceleração do IPCA15 e inflação de serviços"]}'::jsonb, '{"summary": "Scorecard foca em recorrência, experiência integrativa e menor dependência da fundadora.", "customer": ["Elevar NPS para 80+ com experiência leve, humana e integrativa", "Alcançar 40% de clientes em planos de bem-estar recorrentes"], "financial": ["Elevar receita anual para R$ 2M com serviços recorrentes integrativos", "Aumentar margem EBITDA em 5 p.p. via mix premium e custos enxutos"], "learning_growth": ["Desenvolver 100% da equipe em saúde integrativa e experiência Vallen", "Reduzir dependência da fundadora a 30% dos atendimentos estratégicos"], "internal_processes": ["Criar jornada integrada corpo-mente com protocolos padronizados", "Implantar funil digital de leads e agendamento online completo"]}'::jsonb, '{"score": "8.4/10", "summary": "A estratégia recomendada foca em consolidar a Vallen Clinic como clínica boutique de bem-estar integral, com gestão profissional e forte presença digital. Em um contexto de juros SELIC em 14,90% e consumidor mais seletivo, crescer com eficiência (melhor gestão, portfólio claro e digital forte) é mais prudente do que imobilizar capital em nova unidade ou franquias. Os próximos passos são: (1) formalizar o plano de governança e sucessão da fundadora; (2) contratar parceiros para estruturar site, CRM e campanhas digitais; (3) lançar programas de bem-estar integral com precificação adequada ao posicionamento premium; (4) acompanhar, em ciclos trimestrais, métricas de receita, dependência da fundadora, satisfação e compliance regulatório, revisando o plano diante dos gatilhos extraordinários definidos.", "criteria": ["Potencial de crescimento de receita em 3 anos", "Risco operacional e jurídico", "Necessidade de capital e prazo para retorno"], "alternatives": ["Alternativa A – Profissionalizar gestão e escalar presença digital mantendo uma única unidade", "Alternativa B – Expandir capacidade física com segunda unidade em São Paulo", "Alternativa C – Desenvolver modelo de franquias/licenciamento da marca Vallen Clinic"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória que exija >10% de ajuste de custo operacional", "Nova exigência de licenciamento que bloqueie total ou parcialmente a operação", "Decisão judicial que afete diretamente o modelo de negócio de clínicas de saúde/estética", "Falha material de compliance LGPD ou setorial (vazamento de dados, autuação sanitária relevante)", "Entrada de competidor relevante no mesmo nicho e região (clínica boutique ou rede/franquia forte)", "Variação abrupta do câmbio USD/BRL que aumente substancialmente o custo de insumos", "Alterações em normas de publicidade médica/estética que restrinjam campanhas atuais"]}, "score_comparison": "+25% acima da segunda opção", "monitoring_metrics": ["Crescimento de faturamento anual (%) dentro da faixa de R$ 1,2M–1,5M e acima", "Participação da receita não dependente diretamente da agenda da fundadora (%)", "Taxa de ocupação da agenda por profissional e por sala de atendimento (%)", "CAC digital médio (R$ por novo cliente proveniente de canais online)", "NPS / Índice de satisfação do cliente e taxa de recompra em até 6 meses", "Receita recorrente mensal proveniente de programas de bem-estar integral (R$/mês)", "Número de não conformidades de compliance sanitário e LGPD (incidentes/ano)"], "recommended_option": "Alternativa A – Profissionalizar gestão e escalar presença digital mantendo uma única unidade", "final_recommendation": "A melhor opção é a Alternativa A: profissionalizar a gestão e escalar a presença digital mantendo uma única unidade, reduzindo a dependência da fundadora e fortalecendo o posicionamento em bem-estar integral antes de qualquer expansão física ou franquia.", "priority_recommendations": [{"title": "Implantar gestão profissional, governança clínica e sucessão para reduzir dependência da fundadora", "budget": "R$150-250k", "priority": 1, "timeline": "9-12 meses", "description": "Estruturar um modelo de gestão profissional da Vallen Clinic, alinhado à missão/visão, com papéis e processos claros que reduzam a dependência da fundadora (Thalita Mendes). Etapas: (1) diagnóstico organizacional e mapeamento de processos críticos (atendimento, prontuário, agendamento, financeiro); (2) criação de organograma mínimo com liderança assistencial, coordenação administrativa e apoio financeiro/contábil; (3) definição de indicadores (faturamento, uso de sala, satisfação, dependência da fundadora); (4) implementação de protocolos clínicos e de atendimento humanizado coerentes com a proposta de bem-estar integral; (5) plano de sucessão da agenda da fundadora, treinando e posicionando outros profissionais como referências técnicas; (6) revisão de contratos de prestação de serviços, termos de consentimento e políticas internas à luz da LGPD e da regulação sanitária.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Obter parecer jurídico trabalhista e cível para revisão de contratos com profissionais de saúde, termos de consentimento e políticas internas; garantir que qualquer mudança em funções da fundadora respeite contratos sociais existentes; implementar programa básico de compliance (código de conduta, canal de denúncias simplificado, trilha de treinamento em LGPD e biossegurança).", "requires_legal_opinion": true, "regulatory_dependencies": ["Manutenção de Licença Sanitária vigente", "Registro/atualização no CNES, se aplicável", "Nomeação e registro de Responsável Técnico conforme conselho profissional competente", "Adequação contratual e de políticas internas à LGPD e normas de biossegurança"], "requires_statutory_change": false}}, {"title": "Construir ecossistema digital de captação e fidelização alinhado ao bem-estar integral", "budget": "R$80-120k", "priority": 2, "timeline": "6-9 meses", "description": "Desenvolver uma presença digital estruturada que reflita a proposta de valor de bem-estar integral, leveza e sustentabilidade. Etapas: (1) criação ou revisão do site institucional com foco em autoridade clínica, explicação clara de serviços integrativos e conteúdo educativo; (2) implantação de jornada digital de agendamento (landing pages, formulários, integração com sistema de agenda) e automações básicas de CRM (e-mail/WhatsApp conforme LGPD); (3) produção recorrente de conteúdo sobre saúde, estética e bem-estar mental, com ênfase em segurança, individualidade e respeito à natureza; (4) campanhas de mídia digital segmentadas para público B2C classe A/B da região de São Paulo, testando ofertas de avaliação integral e programas contínuos; (5) monitoramento de CAC, LTV e NPS para otimizar investimentos, lembrando que juros SELIC de 14,90% e câmbio de USD/BRL 5,3723 deixam o consumidor mais seletivo e o custo de mídia em alta.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Adequação de política de privacidade e termos de uso à LGPD", "Observância das normas de publicidade médica/estética dos conselhos profissionais", "Controle de consentimento para comunicações de marketing (opt-in, revogação)"], "requires_statutory_change": false}}, {"title": "Estruturar portfólio de bem-estar integral e programas recorrentes de alta experiência", "budget": "R$40-60k", "priority": 3, "timeline": "3-6 meses", "description": "Organizar e comunicar um portfólio claro de programas de bem-estar integral (corpo + mente + autoestima) compatíveis com a missão da Vallen Clinic, priorizando experiências de alto valor percebido em vez de grande volume. Etapas: (1) desenhar 2-3 programas assinaturas (por exemplo, programa de autoestima e pele saudável, programa de bem-estar integrativo com foco em estresse) com protocolos multidisciplinares; (2) padronizar trilhas de atendimento, frequência de retornos e acompanhamentos digitais (teleorientação quando permitido, check-ins remotos); (3) revisar precificação considerando inflação IPCA de 0,09% (12 meses), câmbio sensível em insumos atrelados ao dólar e posicionamento premium; (4) treinar equipe para entrega consistente da experiência “leve, humana e conectada à natureza”; (5) integrar indicadores desses programas (renovação, adesão, satisfação) ao painel de gestão.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Conformidade com normas da ANVISA e conselhos profissionais para cada procedimento incluso nos programas", "Termos de consentimento informado específicos por tipo de procedimento", "Registro e guarda adequada de prontuários e dados sensíveis em conformidade com a LGPD"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 324282, true, false, true, '4RB17552', '2025-12-03 17:12:29.11123+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-02 13:18:46.948871+00'::timestamptz, '2025-12-04 13:08:36.611572+00'::timestamptz, '2025-12-02 13:24:10.957996+00'::timestamptz, NULL)
