INSERT INTO analyses (id, submission_id, enrichment_id, company_id, swot, pestel, porter, okrs, synthesis, tam_sam_som, benchmarking, blue_ocean, growth_hacking, scenarios, bsc, decision_matrix, status, error_message, processing_time_ms, is_visible_to_user, is_blurred, is_public, access_code, access_code_created_at, pdf_url, pdf_generated_at, approved_at, approved_by, sent_at, sent_to, created_at, updated_at, completed_at, deleted_at)
VALUES ('ae094a98-e8f9-4135-bd08-4947fcc2246a', NULL, NULL, NULL, '{"summary": "Santapele deve usar os R$2M para escalar nichos wellness premium via omnichannel e B2B, reforçando dados, eficiência de capital e diferenciação sustentável frente a juros e rivais.", "threats": [{"source": "análise de mercado", "content": "Planejar caixa para SELIC 14,90% e custo alto de capital e estoque", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Defender-se de private labels e importados de baixo custo", "confidence": "Média"}, {"source": "análise de mercado", "content": "Responder à expansão de concorrentes premium com parcerias local", "confidence": "Média"}, {"source": "análise de mercado", "content": "Preparar-se para normas ANVISA/ESG e exigências de rotulagem", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Aproveitar histórico bootstrapped para manter disciplina de capital", "confidence": "Alta"}, {"source": "fato", "content": "Escalar modelo híbrido B2B/B2C para diluir risco de receita", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Usar posicionamento wellness premium para justificar tíquete maior", "confidence": "Média"}, {"source": "fato", "content": "Alavancar faturamento R$1,5–2M como prova de tração a investidores", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Detalhar plano de uso dos R$2M com marcos e ROI por frente", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Mitigar baixa escala frente a Natura/Granado com foco em nichos", "confidence": "Média"}, {"source": "estimativa", "content": "Estruturar função de dados/BI para apoiar decisões de expansão", "confidence": "Média"}, {"source": "estimativa", "content": "Reduzir dependência da rodada atual com melhorias de margem", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Concentrar R$2M em omnichannel integrado (e‑commerce + parceiros)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Firmar contratos âncora com redes hoteleiras e spas de luxo", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Lançar linha clean/sustentável com certificações ESG", "confidence": "Média"}, {"source": "análise de mercado", "content": "Usar CRM/IA para personalizar kits e aumentar ticket médio", "confidence": "Média"}]}'::jsonb, '{"legal": ["RDC ANVISA sobre rotulagem de alérgenos exige revisão fina de portfólio atual", "Regras mais rígidas para termos ''Natural'' e ''Orgânico'' podem demandar certificações", "BPF, ISO 22716 e selos cruelty-free/vegan tendem a virar requisito de grandes clientes"], "social": ["Consumidor seletivo exige custo-benefício ou experiência premium muito bem justificada", "Tendência Clean Beauty e bem-estar reforça aderência da proposta de valor Santapele", "Serviços 0.60% vs comércio -0.30% favorece foco em experiências B2B de spas e hotéis"], "summary": "Juros altos e consumo seletivo exigem uso cirúrgico dos R$ 2M em eficiência, diferenciação premium, omnichannel e adequação regulatória/ESG para fortalecer o nicho wellness B2B/B2C.", "economic": ["SELIC 14.90% a.a. encarece capital; pressiona retorno do investimento de R$ 2M", "IPCA 0.09% (acum. 12 meses) e comércio -0.30% indicam consumo fraco para wellness", "USD/BRL 5.3416 e custos logísticos altos comprimem margens de insumos e embalagens"], "political": ["Reforma Tributária no consumo pode alterar margens de cosméticos premium em 2-3 anos", "Atenção fiscal federal pode elevar carga sobre bens supérfluos como wellness", "Estabilidade política ajuda rodada de R$ 2M, mas com maior escrutínio regulatório"], "environmental": ["Lei de Logística Reversa força redesign de embalagens e gestão de retorno pós-consumo", "Alta em petróleo encarece embalagens plásticas e frete, reforçando apelo sustentável", "Volatilidade em óleos essenciais pressiona fórmulas naturais e planejamento de mix"], "technological": ["Adoção média-alta de e-commerce/CRM exige operação omnichannel madura B2B e B2C", "Personalização via IA abre espaço para rotinas e kits de bem-estar customizados", "DNVBs com marketing de influência intenso elevam custo digital de aquisição"]}'::jsonb, '{"summary": "Mercado de wellness/cosméticos é atrativo em crescimento, mas com rivalidade, substitutos e poder do comprador elevados. A rodada de R$ 2 milhões deve focar em diferenciação de nicho, dados/IA e parcerias B2B para escalar com eficiência.", "buyer_power": "Consumidor seletivo busca custo‑benefício ou experiências premium justificáveis; desemprego 5.6% e IPCA 0.09% (acum. 12 meses) reduzem urgência de gasto, mas alta oferta dá forte poder de escolha sobre Santapele.", "supplier_power": "Insumos atrelados a petróleo e óleos essenciais e frete com diesel pressionam margens; cadeia estável porém cara, com SELIC 14.90% a.a. encarecendo capital de giro e elevando poder de barganha de fornecedores.", "disruption_ai_data": "Personalização via IA e CRM é tendência chave; setor com adoção Média‑Alta favorece DNVBs data‑driven. Santapele precisa estruturar dados 1st party e pilotos de IA em mídia, pricing e sortimento para manter relevância.", "threat_substitutes": "Private labels de grandes varejistas e importados asiáticos com preços agressivos ampliam substitutos; adoção tecnológica Média‑Alta e e‑commerce facilitam troca, exigindo proposta única de wellness brasileiro.", "competitive_rivalry": "Alta rivalidade com Natura/Boticário e DNVBs; concentração alta e M&A ativos em HPPC (CAGR 7-9%) forçam Santapele a aprofundar nicho wellness brasileiro e fortalecer diferenciação em B2B hotelaria/spas.", "threat_new_entrants": "Barreiras médias (ANVISA, BPF, logística) e SELIC 14.90% a.a. limitam fábricas próprias, mas DNVBs digitais entram com CAPEX leve; nichos clean beauty seguem atraentes, mantendo ameaça moderada e constante.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Reforçar posicionamento em wellness brasileiro premium, com linhas exclusivas e storytelling profundo para B2C e B2B (hotelaria/spas) reduzindo comparabilidade com concorrentes e substitutos.", "Alocar parte dos R$ 2 milhões em dados e IA: CRM unificado, segmentação avançada, personalização de ofertas e atribuição de mídia para reduzir CAC e aumentar LTV nos canais digitais.", "Estruturar parcerias âncora com 2–3 redes hoteleiras e spas de referência e marketplaces premium, com contratos plurianuais, co-branding e programas de experiência para travar demanda recorrente.", "Mitigar riscos de fornecimento com múltiplos fornecedores críticos, revisão de embalagens e otimização logística, usando a rodada para negociar volumes e melhorar capital de giro em ambiente de SELIC 14.90% a.a."], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Omnichannel e ecossistemas com redes hoteleiras/spas, marketplaces premium e programas de logística reversa tornam parcerias críticas; consolidação via M&A favorece marcas nichadas prontas para alianças.", "threat_new_entrants_intensity": "Média", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": ""}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Contratar equipe core (3-4 pessoas), implementar CRM/BI, fechar 3 pilotos B2B hotelaria, otimizar e-commerce. Investimento: R$ 600K", "Médio Prazo (6-12 meses): Escalar B2B para 10 contas, lançar linha de rituais exclusivos, ativar omnichannel B2C com dados. Investimento: R$ 900K", "Longo Prazo (12-18 meses): Consolidar 20+ contas B2B, preparar métricas para Series A (R$ 8-10M), expandir geograficamente. Investimento: R$ 500K + reserva"], "key_findings": ["Oceano Azul identificado: parceria estratégica com hotelaria via rituais proprietários e modelo SaaS de serviços diferencia da competição", "CAC B2B potencialmente 3-5x menor que B2C com LTV superior; priorizar este canal para eficiência de capital", "Dados e IA são enablers críticos: investir em CRM/BI antes de escalar aquisição para otimizar margens"], "main_findings": ["Força: Marca consolidada em wellness com 12 anos de operação bootstrapped eficiente e modelo híbrido B2B/B2C que reduz risco", "Fraqueza: Escala limitada (1-10 funcionários) e dependência de capital externo para competir com players como Granado e Natura", "Oportunidade: Mercado de wellness cresce 7-9% ao ano; nicho B2B hotelaria/spas pouco explorado por grandes players", "Ameaça: Juros altos (14,9%), marcas próprias de varejistas e importados asiáticos pressionam margens"], "important_notes": ["Reservar 15-20% do capital (R$ 300-400K) como caixa de segurança dado cenário macroeconômico adverso", "Contratações críticas: Head Comercial B2B e Analista de Dados antes de escalar marketing", "Validar unit economics B2B antes de comprometer mais de R$ 500K neste canal"], "central_challenge": "Definir alocação estratégica de R$ 2M captados para escalar Santapele em wellness B2B/B2C, maximizando retorno e preparando próxima rodada de investimento.", "executive_summary": "Santapele deve alocar os R$ 2M em três frentes: tecnologia/dados (35%), expansão B2B hotelaria/spas (40%) e fortalecimento omnichannel B2C (25%). Com juros a 14,9% e consumo seletivo, priorizar eficiência de capital e diferenciação premium. Meta: dobrar receita em 18 meses, atingindo R$ 4M, posicionando para Series A de R$ 8-10M.", "strategic_priorities": ["Estruturar operação B2B hotelaria/spas com 10 contas âncora até mês 12", "Implementar stack de dados (CRM + BI) para decisões baseadas em evidências", "Desenvolver linha de rituais proprietários como barreira competitiva"], "consistency_validation": {"flags": ["Equipe atual (1-10) insuficiente para executar plano completo; contratações são pré-requisito crítico", "Meta de dobrar receita em 18 meses é agressiva dado cenário macro; considerar 24 meses como alternativa conservadora", "Validação de unit economics B2B ainda pendente; plano assume premissas otimistas neste canal"], "legal_alignment": true, "capacity_alignment": false, "financial_alignment": true, "overall_realism_score": 7}, "overall_recommendation": "Executar plano focado em B2B hotelaria como motor de crescimento eficiente, usando tecnologia para escalar B2C. Os R$ 2M levam a empresa a R$ 4M de receita em 18 meses, posicionando para Series A com tese validada de wellness premium omnichannel."}'::jsonb, '{"sam": "R$ 200M - 400M", "som": "R$ 6M - 50M", "tam": "R$ 120B - 180B", "cagr": "+6-10% a.a. (macro_context HPPC 7-9% ajustado por tendências clean/sustentável)", "summary": "Mercado HPPC Brasil é grande (TAM R$120-180B). Nicho wellness premium acessível (SAM R$200-400M) permite SOM realista R$16-35M/ano para Santapele.", "assumptions": ["TAM HPPC Brasil ~R$120-180B = 8-10% do varejo R$1,5-2T (benchmark setorial)", "SAM wellness premium B2B/B2C ~0,15-0,3% do TAM via filtros RACE/AIM", "SOM PME = 8-15% do SAM, alvo R$6-50M/ano (benchmark PME HPPC Brasil)"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 16M - 35M", "market_share": "8-10%"}, "optimistic": {"probability": 20, "value_range": "R$ 30M - 50M", "market_share": "15-18%"}, "conservative": {"probability": 30, "value_range": "R$ 6M - 16M", "market_share": "3-4%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 140B - 160B"}, "optimistic": {"probability": 20, "value_range": "R$ 160B - 180B"}, "conservative": {"probability": 30, "value_range": "R$ 120B - 140B"}}, "confidence_level": 60, "calculation_notes": "TAM=8-10% do varejo Brasil; SAM restringe wellness premium B2B/B2C via RACE/AIM; SOM=8-15% do SAM alinhado a R$6-50M/ano PME.", "data_sources_used": {"direct_data": ["Receita anual Santapele ~R$1,5-2,0M (submitted_data)", "Setor: Varejo - wellness / HPPC Brasil (macro_context.industry_trends)"], "proxy_calculations": ["TAM HPPC=8-10% do varejo Brasil R$1,5-2T (instruções benchmark)", "SAM wellness premium=0,15-0,3% do TAM filtrando B2B hotelaria/spa e B2C premium", "SOM=8-15% do SAM compatível com faixa R$5-50M/ano para PME"], "benchmark_extrapolations": ["Benchmark varejo/e-commerce Brasil R$1,5-2T (instrução do usuário)", "Crescimento HPPC 7-9% a.a. (macro_context.industry_trends.growth_rate)"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "Santapele é nicho wellness premium com players fortes como Natura/Granado. Mercado nichado permite SOM R$16-35M/ano.", "best_practices": ["Portfólio wellness premium com identidade brasileira, alinhado às tendências clean beauty e experiência.", "Estratégia omnichannel enxuta integrando e-commerce, B2B hoteleiro/spa e poucos pontos físicos selecionados.", "Operação bootstrapped com disciplina de caixa e margens saudáveis, atraente para investidores."], "performance_gaps": ["Baixa notoriedade de marca frente a Natura/Boticário e pouca presença em mídia de massa.", "Escala limitada de canais físicos; dependência maior de e-commerce e poucos pontos B2B âncora.", "Menor investimento em dados, CRM avançado e personalização vs DNVBs digitais e grandes grupos."], "competitors_analyzed": ["Granado Pharmácias", "Avatim", "Natura &Co", "L''Occitane au Brésil"]}'::jsonb, '{"raise": ["Curadoria de rituais de bem-estar exclusivos para hotelaria e spas", "Padrão de dados de uso do hóspede para personalizar amenities", "Certificações de sustentabilidade e brasilidade em ingredientes"], "create": ["Plataforma de IA para co-criar amenities personalizados com redes hoteleiras", "Modelo SaaS de bem-estar: assinatura de reposição, treinamento e dados B2B", "Experiências imersivas Santapele in-room e em spas como diferencial do hotel"], "reduce": ["Investimento em lojas físicas próprias de alto CAPEX", "Complexidade de portfólio B2C com baixa margem", "Uso de insumos importados voláteis e caros"], "summary": "Santapele sai da disputa de prateleira de cosméticos e vira parceira estratégica de bem-estar para hotelaria e spas, combinando rituais proprietários, dados/IA e modelo SaaS de serviços. O capital de R$ 2M acelera tecnologia, portfólio focado em experiências e expansão B2B escalável, criando uma posição difícil de copiar por players tradicionais.", "eliminate": ["Linha extensa de SKUs genéricos sem narrativa de bem-estar", "Dependência de promoções de preço tipo farmácia/perfumaria", "Marketing de influência pulverizado e pouco mensurável"], "new_value_curve": "Migração de marca de cosméticos premium para plataforma de bem-estar data-driven focada em rituais personalizados para hotelaria e alta renda"}'::jsonb, '{"summary": "Direcionar R$2M para aquisição omnichannel focada em hotéis/spas e B2C premium, com BI e CRM para elevar margens, LTV e previsibilidade de receita.", "leap_loop": {"name": "LEAP Loop", "type": "aquisição", "steps": ["Atrair hotéis/spas âncora e B2C premium via mídia paga segmentada, SEO e parcerias omnichannel", "Engajar com experiências sensoriais em hotéis/spas e conteúdo educativo de wellness nas jornadas digitais", "Converter em compras/kits teste com oferta de primeira compra, amostras e check-out simplificado", "Estimular indicações e UGC com programa de recomendação, kits compartilháveis e co-criações com spas"], "metrics": ["CAC por canal (mídia paga, SEO, indicação, parcerias B2B)", "Taxa lead qualificado→primeira compra (B2B e B2C)", "Novos contratos âncora com hotéis/spas por trimestre"], "bottleneck": "Falta de dados/BI para provar ROI por canal, travando decisão de onde investir os R$2M em aquisição em escala"}, "scale_loop": {"name": "SCALE Loop", "type": "monetização", "steps": ["Entregar rituais de bem-estar com produtos clean, performance consistente e experiência premium B2B/B2C", "Monetizar via contratos B2B recorrentes, bundles sazonais B2C e assinaturas de caixas wellness", "Gerar recorrência com CRM, fidelidade omnichannel, reposição automática e pós-venda ativo B2B/B2C", "Aumentar LTV com upsell de linhas premium, cross-sell de kits temáticos e co-branding com hotéis/spas"], "metrics": ["LTV por segmento (B2B hotéis/spas, B2C premium)", "Taxa de recompra em 90/180 dias", "Receita de expansão por cliente (upsell, cross-sell, contratos)"], "bottleneck": "Baixa visibilidade de margens e LTV por segmento, dificultando focar em clientes mais rentáveis e reduzir dependência de capital"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC se mantém em 14,90% e inflação em 0,09% (12 meses), com PIB perto de 2,20% e serviços em 0,60%. Consumo segue seletivo, pressionando tíquete médio no nicho wellness. Os R$ 2M permitem reforçar caixa, eficiência operacional e testes controlados de canais B2B/B2C, alongando runway sem aposta agressiva em marketing ou lojas físicas.", "probability": 60, "required_actions": ["Alocar ~40% dos R$ 2M em eficiência: margem, logística, renegociação com fornecedores e automação de e-commerce/CRM.", "Destinar ~30% a crescimento seletivo: pilotos omnichannel, cross-sell B2B (hotéis/spas) e kits de alta margem no B2C.", "Reservar ~20% como colchão de caixa para 18–24 meses, protegendo operação em juros de 14,90% a.a.", "Planejar próxima rodada com foco em métricas de coorte (LTV/CAC, payback) e expansão regional validada."]}, "summary": "Santapele opera em ambiente de juros altos (14,90% a.a.), consumo seletivo e câmbio em R$ 5,35/USD. O plano para os R$ 2M deve combinar caixa, eficiência e testes de crescimento omnichannel. Preparar-se para três trajetórias macro, com gatilhos claros de aceleração ou defesa, reduz o risco e aumenta a atratividade para investidores.", "optimistic": {"name": "Cenário Otimista", "description": "Com SELIC caindo de 14,90% para perto de 10% e PIB acima de 3%, consumo em wellness premium reage apesar do comércio hoje em -0,30%. Dólar em torno de R$ 5,35/USD reduz volatilidade. Santapele usa os R$ 2M para acelerar omnichannel B2B/B2C, ampliar mix clean beauty e ganhar espaço frente a Natura &Co e Granado.", "probability": 20, "required_actions": ["Destinar maior parte dos R$ 2M a crescimento: mídia de performance, influenciadores e expansão B2B em redes hoteleiras e spas.", "Investir em CRM e personalização para elevar LTV, com programas de assinatura e kits de experiência premium.", "Acelerar certificações ESG e clean beauty para diferenciar frente a marcas próprias e importados asiáticos."]}, "pessimistic": {"name": "Cenário Pessimista", "description": "Alta de risco fiscal mantém SELIC acima de 15% e dólar acima de R$ 5,35/USD. Comércio aprofunda queda além de -0,30% e desemprego supera 6,5%. Consumo premium retrai; hotéis e spas cortam contratos. Os R$ 2M viram essencialmente colchão de caixa e digitalização enxuta, focando ticket médio maior em nichos superpremium e exportação piloto.", "probability": 20, "required_actions": ["Preservar caixa: cortar despesas não essenciais, congelar contratações e priorizar margens sobre crescimento.", "Reprecificar portfólio, criando linhas menores de alto valor percebido para manter ticket e reduzir churn.", "Diversificar receitas com B2B resiliente (spas médicos, clínicas) e canais digitais diretos ao consumidor fiel."]}, "mitigation_tactics": ["Planejar uso dos R$ 2M em tranches com marcos de desempenho (LTV/CAC, margem bruta, giro de estoque), podendo desacelerar investimento se o macro piorar.", "Travamento parcial de custos em dólar e contratos logísticos, reduzindo impacto da volatilidade em R$ 5,35/USD.", "Fortalecer dados de cliente (CRM, coortes) para ajustar rapidamente mix e canais diante de consumo seletivo.", "Garantir compliance ANVISA/ESG desde já para evitar multas e aproveitar reformas e novas regras como vantagem competitiva."], "early_warning_signals": ["Trajetória da SELIC vs 14,90% a.a. e mudanças nas expectativas do mercado de juros de longo prazo.", "Variação da inflação (IPCA 0,09% em 12 meses) e impacto sobre custos de insumos e embalagens.", "Indicadores de comércio (-0,30%) e desemprego (5,60%) refletidos em queda de ticket médio e aumento de inadimplência B2B."]}'::jsonb, '{"summary": "O portfólio, os rituais e a plataforma de dados/IA se alinham para escalar receita B2B recorrente, posicionando a Santapele como parceira estratégica de bem-estar em hotelaria e spas.", "customer": ["Ser parceira estratégica de bem-estar em 50 hotéis e spas premium", "Atingir NPS ≥ 70 entre parceiros B2B com foco em experiências"], "financial": ["Elevar receita anual para R$ 4M em 24 meses com carteira B2B recorrente", "Alcançar 30% da receita via contratos SaaS com hotelaria e spas"], "learning_growth": ["Treinar 100% da equipe em vendas consultivas para hotelaria e spas", "Formar time de produto digital com 3 talentos-chave em 12 meses"], "internal_processes": ["Padronizar 5 rituais proprietários com protocolos escaláveis até 12 meses", "Implantar plataforma de dados e IA para personalização B2B"]}'::jsonb, '{"score": "8.4/10", "summary": "A matriz multicriterial (ROI, risco e flexibilidade de caixa) indica que a Alternativa A oferece o melhor equilíbrio para Santapele Cosméticos no contexto atual de SELIC em 14,90% a.a., consumo seletivo e câmbio em torno de USD/BRL 5,3416. Em vez de apostar em uma expansão agressiva unilateral (apenas B2C digital ou apenas B2B), o plano propõe: (i) blindar caixa e capital de giro para 6-9 meses, (ii) ganhar eficiência logística, operacional e de margem, (iii) construir infraestrutura omnichannel e base de dados robusta, e (iv) testar de forma disciplinada tanto o canal B2B estruturado quanto inovações em portfólio e experiências phygital. As três recomendações prioritárias distribuem cerca de R$ 2 milhões entre núcleo de caixa/eficiência/omnichannel (prioridade 1), crescimento B2B com contratos-padrão e contas âncora (prioridade 2) e um fundo de experimentação em produtos/experiências (prioridade 3). Do ponto de vista jurídico, o risco é predominantemente baixo a médio, concentrado em contratos B2B, LGPD, rotulagem ANVISA e CDC, sem necessidade de alteração estatutária. Recomenda-se: obter parecer jurídico para padronizar contratos B2B e políticas de dados; revisar rotulagem e claims; e adotar um ciclo de revisão trimestral com gatilhos extraordinários (mudanças regulatórias relevantes, novas exigências de licenciamento, decisões judiciais ou incidentes de compliance). Com métricas claras de receita por canal, margem, CAC/LTV, recompra, omnicanalidade e satisfação, a empresa poderá demonstrar para investidores até onde os R$ 2 milhões levam (runway, crescimento e maturidade de canais) e definir com clareza a próxima fase de captação (possível rodada seed/Series A focada em escala dos canais mais validados).", "criteria": ["Retorno sobre investimento em 24-36 meses (ROI)", "Risco financeiro e regulatório", "Flexibilidade de caixa e resiliência a cenários macro (SELIC 14,90% a.a. e USD/BRL 5,3416)"], "alternatives": ["Alternativa A - Estratégia Equilibrada: Caixa + Eficiência + Omnichannel", "Alternativa B - Crescimento Digital Agressivo (Foco B2C)", "Alternativa C - Expansão B2B e Presença Física Selecionada"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["Mudança regulatória que exija >10% de ajuste de custo", "Nova exigência de licenciamento que bloqueie operação", "Decisão judicial que afete modelo de negócio", "Falha de compliance LGPD/setorial", "Entrada de competidor relevante no nicho premium de wellness", "Variação de câmbio USD/BRL superior a 15% em 90 dias", "Queda de receita líquida >20% em dois trimestres consecutivos"]}, "score_comparison": "+18% acima da segunda opção", "monitoring_metrics": ["Receita mensal total e por canal (B2B vs B2C, online vs offline)", "Margem bruta (%) e margem de contribuição por linha de produto", "CAC, LTV e payback de marketing (meses) por canal principal", "Taxa de recompra em 6 e 12 meses (%) e ticket médio", "Participação das vendas omnichannel (pedidos com interação multi-canal)", "Giro de estoque (dias) e ruptura de itens-chave", "NPS/CSAT de clientes B2B e B2C e índice de reclamações (Procon/Redes)"], "recommended_option": "Alternativa A - Estratégia Equilibrada: Caixa + Eficiência + Omnichannel", "final_recommendation": "A melhor opção é a Alternativa A - Estratégia Equilibrada: Caixa + Eficiência + Omnichannel, combinando proteção de caixa no ambiente de juros altos com testes estruturados de crescimento omnichannel e base contratual/operacional sólida para a próxima rodada.", "priority_recommendations": [{"title": "Alocação Núcleo: Caixa, Eficiência e Fundos para Testes Omnichannel", "budget": "R$1.000.000-1.100.000", "priority": 1, "timeline": "12-18 meses", "description": "Destinar cerca de 50-55% da rodada (R$ 1,0-1,1M) para: (i) reforço de capital de giro (estoque crítico e caixa mínimo de 6-9 meses de OPEX), (ii) aumento de eficiência operacional (logística, sistemas, margem) e (iii) infraestrutura omnichannel (integração e-commerce, marketplaces, CRM e atendimento). Foco em preservar caixa em cenário de juros altos (SELIC 14,90% a.a.), reduzir custo unitário e criar base de dados de clientes (B2B e B2C) para os próximos ciclos de crescimento. Viabilidade jurídica: alta, sem necessidade de alteração societária, mas com atenção a contratos com plataformas, fornecedores e LGPD.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Viabilidade legal: alta, sem alteração contratual social. Complexidade institucional: baixa a média, envolvendo apenas a administração e eventuais ajustes com plataformas/parceiros. Recomenda-se parecer jurídico prévio para: (i) revisar termos de uso de marketplaces e contratos de serviços de CRM/logística; (ii) adequar políticas de privacidade, cookies e consentimento LGPD; (iii) validar conformidade de rotulagem com as últimas RDCs da ANVISA. Medidas de mitigação: mapear todos os fluxos de dados pessoais; firmar contratos de operador LGPD com fornecedores de tecnologia; implementar política de resposta a incidentes de dados; revisar rotulagem e claims publicitários para evitar riscos de responsabilidade civil e autuações. Caso o risco se eleve (p.ex. entrada em novos mercados com regras específicas), adotar alternativa de menor risco reduzindo escopo inicial de canais e priorizando apenas aqueles com menor complexidade regulatória.", "requires_legal_opinion": true, "regulatory_dependencies": ["Adequação contínua às normas da ANVISA (registro e rotulagem de cosméticos)", "Conformidade com LGPD para uso de CRM, dados de clientes e marketing omnichannel", "Observância ao Código de Defesa do Consumidor e Lei do E-commerce nas vendas online", "Adequação à Lei de Logística Reversa para embalagens"], "requires_statutory_change": false}}, {"title": "Trilha de Crescimento B2B Estruturado (Hotelaria, Spas e Parceiros de Wellness)", "budget": "R$500.000-700.000", "priority": 2, "timeline": "9-15 meses", "description": "Alocar cerca de 25-30% da rodada (R$ 500-700k) para fortalecer e escalar o canal B2B em nichos premium (hotelaria, spas, clínicas e espaços de bem-estar). Ações: (i) modelagem de pacotes de fornecimento e amenities, (ii) criação de playbook comercial B2B, (iii) estruturação de contratos-padrão com SLAs claros, (iv) testes em 10-20 contas âncora antes de expansão mais ampla. Objetivo: construir receita recorrente mais resiliente ao consumo seletivo, ampliando a penetração da marca Santapele Cosméticos em experiências de hospitalidade wellness.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Viabilidade legal: boa, baseada em modelos consolidados no setor de hotelaria/spas. Complexidade institucional: média, pela necessidade de negociação com várias redes e possíveis diferentes regimes contratuais. Recomenda-se: (i) obter parecer jurídico para desenvolver contratos-padrão B2B com cláusulas claras de responsabilidade, devolução, recalls e propriedade de marca; (ii) criar anexos técnicos que estabeleçam padrões de qualidade, armazenamento e uso dos produtos; (iii) revisar comunicações e materiais co-branded para evitar infrações de ANVISA e publicidade enganosa. Mitigação adicional: utilizar fases-piloto com parceiros dispostos a testar modelos contratuais; sempre que possível, priorizar formatos de fornecimento com menor risco jurídico (p.ex. venda de produtos padronizados, evitando serviços que confundam fronteira com atividade clínica).", "requires_legal_opinion": true, "regulatory_dependencies": ["Contratos B2B com cláusulas de responsabilidade civil e garantia alinhadas ao Código Civil e CDC (quando aplicável ao consumidor final)", "Conformidade ANVISA para produtos fornecidos como amenities e para uso profissional", "Adequação a normas de publicidade e claims em materiais co-branded com redes hoteleiras", "Eventuais exigências contratuais de seguros de responsabilidade civil profissional (a depender dos parceiros)"], "requires_statutory_change": false}}, {"title": "Portfólio e Marca: Testes de Inovação de Produtos e Experiências Omnichannel", "budget": "R$200.000-300.000", "priority": 3, "timeline": "6-12 meses", "description": "Reservar cerca de 10-15% da rodada (R$ 200-300k) para um fundo de experimentação controlada em produtos e experiências omnichannel: (i) lançamento de 2-3 linhas ou kits temáticos de alto potencial (ex.: bem-estar para viagem, autocuidado em casa, experiências de spa em casa), (ii) testes de formatos de assinatura ou bundles, (iii) pilotos de experiências phygital (parcerias com spas, hotéis ou eventos de wellness com venda integrada online/offline). Foco em aprender, gerar dados de demanda e fortalecer o posicionamento de Santapele como marca de wellness premium brasileira, preparando storytelling para próxima rodada de captação.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Análise de rotulagem e registro ANVISA para eventuais novos SKUs", "Adequação de materiais de marketing às normas de publicidade e ao CDC", "Conformidade LGPD em ações promocionais e eventos com coleta de dados"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 190052, false, false, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-02 02:36:22.352656+00'::timestamptz, '2025-12-02 02:39:32.290355+00'::timestamptz, '2025-12-02 02:39:32.141784+00'::timestamptz, NULL)
